#include "WindowModel.hpp"
#include <cstdio>
using namespace mhmvalidation;
namespace {
unsigned checks=0;
void Check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);++checks;}
Snapshot Sample(){Snapshot s;s.phase=Phase::Holding;s.started=true;s.caseCount=25;s.stepCount=9;s.caseIndex=1;s.stepIndex=2;s.caseId="C01";s.caseTitle="合成组合";s.reference.mode="BASELINE";s.reference.liveIds.resize(489);s.observation.result=MHM_OK;for(unsigned i=0;i<30;++i)s.rows.push_back({"完全な源名_眉と目_"+std::to_string(i),"key_"+std::to_string(i),.5f,i<25});return s;}
void TestFullUnicodeLabels(){auto s=Sample();s.rows[0].source=std::string(900,'x')+"完整末尾_目";auto m=MakeWindowModel(s);Check(m.details.find(Wide(s.rows[0].source))!=m.details.npos,"complete long source name and ending preserved");Check(m.details.find(L"key_29")!=m.details.npos&&m.details.find(L"完全な源名")!=m.details.npos,"complete IDs and Japanese labels");bool rejected=false;s.rows[0].source=std::string("\xc0\xaf",2);try{(void)MakeWindowModel(s);}catch(const std::exception&){rejected=true;}Check(rejected,"bad UTF8 cannot become question marks");}
void TestThirtyKeyCaseRows(){auto s=Sample();auto m=MakeWindowModel(s);Check(m.details.find(L"固定 25")!=m.details.npos&&m.details.find(L"变化 5")!=m.details.npos,"all fixed/varying rows counted");for(const auto& r:s.rows)Check(m.details.find(Wide(r.id))!=m.details.npos,"all thirty runtime IDs displayed");s.phase=Phase::NotStarted;s.started=false;m=MakeWindowModel(s);Check(m.details.find(L"预览")!=m.details.npos,"unstarted case rows are previews");}
void TestPendingButtons(){auto s=Sample();s.phase=Phase::WaitingApply;s.pending=true;auto m=MakeWindowModel(s);for(auto a:{Action::Begin,Action::PreviousCase,Action::NextCase,Action::PreviousStep,Action::NextStep,Action::RepeatStep})Check(!m.buttons.at(a),"pending command disabled");Check(m.buttons.at(Action::ZeroAll)&&m.buttons.at(Action::End),"pending cleanup stays available");s=Sample();s.caseIndex=0;s.stepIndex=0;m=MakeWindowModel(s);Check(!m.buttons.at(Action::PreviousCase)&&!m.buttons.at(Action::PreviousStep),"first bounds");s.caseIndex=24;s.stepIndex=8;m=MakeWindowModel(s);Check(!m.buttons.at(Action::NextCase)&&!m.buttons.at(Action::NextStep),"last bounds");s.evidenceComplete=false;m=MakeWindowModel(s);Check(!m.buttons.at(Action::RepeatStep)&&m.buttons.at(Action::ZeroAll)&&m.buttons.at(Action::End),"incomplete evidence preserves cleanup only");}
void TestStatusWording(){auto s=Sample();s.pending=true;s.phase=Phase::WaitingApply;Check(MakeWindowModel(s).status.find(L"已提交")!=std::wstring::npos,"accepted distinct wording");s.pending=false;s.phase=Phase::Holding;Check(MakeWindowModel(s).status.find(L"核心报告已应用")!=std::wstring::npos,"application is core report");s.phase=Phase::Covered;Check(MakeWindowModel(s).status.find(L"其他来源")!=std::wstring::npos,"ownership covered wording");s.phase=Phase::Interrupted;s.ending=true;Check(MakeWindowModel(s).status.find(L"归零未确认")!=std::wstring::npos,"unconfirmed zero explicit");s.phase=Phase::Ended;s.finished=true;s.normalEnd=true;auto m=MakeWindowModel(s);Check(m.status.find(L"其他来源")!=m.status.npos,"release can restore another source");for(const auto p:{Phase::NotReady,Phase::NotStarted,Phase::WaitingApply,Phase::Holding,Phase::WaitingZero,Phase::Covered,Phase::Interrupted,Phase::Ending,Phase::Ended}){s.phase=p;m=MakeWindowModel(s);Check(m.status.find(L"视觉通过")==m.status.npos&&m.status.find(L"视觉验收通过")==m.status.npos,"no automatic visual pass status");}}
void TestClosePurgesQueuedCommands(){WindowCommands queue;queue.Push(Action::Begin);queue.Push(Action::NextStep);queue.Push(Action::End);queue.Push(Action::NextCase);Check(queue.closing&&queue.actions.size()==1&&queue.actions.front()==Action::End,"close purges queued nonzero commands before SDK dispatch");WindowCommands zero;zero.Push(Action::NextStep);zero.Push(Action::ZeroAll);Check(zero.actions.size()==1&&zero.actions.front()==Action::ZeroAll,"zero supersedes unprocessed nonzero command");}
}
int main(){try{TestFullUnicodeLabels();TestThirtyKeyCaseRows();TestPendingButtons();TestStatusWording();TestClosePurgesQueuedCommands();std::printf("PASS: %u window model checks\n",checks);return 0;}catch(const std::exception& e){std::printf("FAIL: %s\n",e.what());return 1;}}
